CustomField.formula:
IF( SM_Full_Payment__c = FALSE,
 IF(SM_AC_collected__c = TRUE, 
  IF(SM_Next_installment_date__c > TODAY(), 
    IF(MONTH(SM_Next_installment_date__c) - 1 = MONTH(TODAY()), 
      0, 
     CEILING(MONTH( TODAY()) + (12*(YEAR( TODAY())-YEAR(SM_Next_installment_date__c))) - MONTH(SM_Next_installment_date__c))
    ), 
    IF(SM_Plan_Months__c <> 99
							, SM_Plan_Months__c - SM_Charged_SB_Fees2__c
       , CEILING(((YEAR(TODAY()) - YEAR(SM_Next_installment_date__c))*12) + (MONTH(TODAY()) - MONTH(SM_Next_installment_date__c)))
	)
  ), 
  IF(SM_AC_start_date__c > TODAY(), 
    0, 
    IF(ISNULL(SM_AC_Split_Date__c), 
      1 - SM_Charged_AC_Fees__c, 
      IF(SM_AC_Split_Date__c > TODAY(), 
        0, 
        2 - SM_Charged_AC_Fees__c
      )
    )
  )
 )
 ,0
)
